package com.yeyamo_mobile.api.feed_service.infrastructure.persistence;import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;@Entity@Table(name="feed_post_metrics")public class FeedMetricEntity{@Id private UUID postId;@Column(nullable=false)private long likes;@Column(nullable=false)private long comments;@Column(nullable=false)private long shares;@Column(nullable=false)private long favorites;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;public UUID getPostId(){return postId;}public void setPostId(UUID v){postId=v;}public long getLikes(){return likes;}public void setLikes(long v){likes=v;}public long getComments(){return comments;}public void setComments(long v){comments=v;}public long getShares(){return shares;}public void setShares(long v){shares=v;}public long getFavorites(){return favorites;}public void setFavorites(long v){favorites=v;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}public long getVersion(){return version;}public void setVersion(long v){version=v;}}
